// Injeta cada etapa preventiva no cronograma da sua cultura, mantendo a ordem por dia.
for (const [id, etapa] of Object.entries(MANEJO_PREVENTIVO)) {
  const c = CULTURAS[id];
  if (!c || !Array.isArray(c.cronograma)) continue;
  const { dose2, ...limpa } = etapa; // descarta campos auxiliares eventuais
  c.cronograma = [...c.cronograma, limpa].sort((a, b) => a.dia - b.dia);
}

// ── Adubações recorrentes expandidas em linhas datadas ────────────────────────
// A pedido: nada de "aplicar a cada X dias" só na descrição — cada aplicação de
// CAMPO vira uma etapa própria e datada no cronograma (adubação dia X, dia Y…).
// As rotinas de VIVEIRO (pulverização a cada 3 dias) permanecem agrupadas nas
// etapasViveiro. Cada série é gerada de `inicio` até `ate`, a cada `intervalo`.
const ADUBACAO_RECORRENTE = {
  maracuja: {
    ate: 330,
    series: [
      { inicio: 8,  intervalo: 15, tipo: 'foliar', etapa: 'Foliar — Crop Set (bioestimulante)', produto: 'Crop Set (ou bioestimulante equivalente)', dose: '10 mL / 20 L de água', forma: 'Pulverização foliar pela manhã ou no fim da tarde', descricao: 'Bioestimulante com micronutrientes que melhora o pegamento de flores e frutos e reduz o abortamento floral — o maior gargalo do maracujá. Aplicação quinzenal; alterne o dia com a foliar Fruit Liqui Plex.' },
      { inicio: 15, intervalo: 15, tipo: 'foliar', etapa: 'Foliar — Fruit Liqui Plex', produto: 'Fruit Liqui Plex (ou foliar complexado equivalente)', dose: '50 mL / 20 L de água', forma: 'Pulverização foliar — alternar os dias com o bioestimulante', descricao: 'Foliar complexado com cálcio, boro e micronutrientes, voltado à formação e à qualidade do fruto: casca firme, bom enchimento e menos deformação. Aplicação quinzenal.' },
      { inicio: 30, intervalo: 20, tipo: 'adubo',  etapa: 'Adubação de cobertura — MAP 11-52 (fertirrigação)', produto: 'MAP 11-52 (fosfato monoamônico)', dose: '20 g/planta', forma: 'Dissolver na água e aplicar por fertirrigação/rega. O MAP é solúvel — ideal para cobertura; NÃO se usa superfosfato aqui, pois o fósforo é pouco móvel no solo e o superfosfato mal se dissolve.', descricao: 'Fósforo solúvel + nitrogênio em cobertura, para raízes e floração. Como o P é pouco móvel no solo, entrega-se dissolvido (MAP), levando o nutriente até a zona radicular pela água.' },
      { inicio: 50, intervalo: 30, tipo: 'adubo',  etapa: 'Cobertura nitrogenada — Sulfato de amônia', produto: 'Sulfato de amônia (21% N + 24% S)', dose: '50 g/planta', forma: 'Solo na projeção da copa + irrigação', descricao: 'Nitrogênio de pronta absorção + enxofre para sustentar o crescimento e a emissão de ramos produtivos. A partir dos 50 dias a dose sobe de 30 para 50 g/planta.' },
      { inicio: 60, intervalo: 30, tipo: 'adubo',  etapa: 'Cobertura de cálcio — Nitrato de cálcio', produto: 'Nitrato de cálcio (15,5% N + 19% Ca)', dose: '45 g/planta', forma: 'Solo na projeção da copa ou fertirrigação + irrigação', descricao: 'Nitrogênio nítrico imediato + cálcio solúvel. O cálcio firma a casca, reduz rachadura e aumenta a vida pós-colheita — e não se redistribui na planta, então precisa chegar continuamente. A partir dos 60 dias a dose sobe de 20 para 45 g/planta.' },
      { inicio: 90, intervalo: 30, tipo: 'adubo',  etapa: 'Adubação de produção — 20-00-20', produto: 'Adubo granulado 20-00-20', dose: '70 g/planta', forma: 'Solo na projeção da copa + irrigação', descricao: 'A dupla da produção: nitrogênio mantém as brotações novas (onde nascem as flores) e potássio enche o fruto — peso, açúcar e acidez. O maracujá é muito exigente em potássio.' },
    ],
  },
};

function expandirRecorrentes(cultura) {
  const spec = ADUBACAO_RECORRENTE[cultura.id];
  if (!spec || !Array.isArray(cultura.cronograma)) return;
  const extras = [];
  for (const s of spec.series) {
    let n = 0;
    for (let dia = s.inicio; dia <= spec.ate; dia += s.intervalo) {
      n += 1;
      extras.push({
        dia,
        etapa: `${s.etapa} (nº ${n})`,
        produto: s.produto,
        dose: s.dose,
        forma: s.forma,
        descricao: s.descricao,
        tipo: s.tipo,
      });
    }
  }
  cultura.cronograma = [...cultura.cronograma, ...extras].sort((a, b) => a.dia - b.dia);
}
for (const id of Object.keys(ADUBACAO_RECORRENTE)) {
  if (CULTURAS[id]) expandirRecorrentes(CULTURAS[id]);
}

// Lista para os seletores de cultura — em ordem alfabética (pt-BR, respeita acentos).
export const CULTURAS_LIST = Object.values(CULTURAS)
  .sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt-BR', { sensitivity: 'base' }));
